SELECT "membership"."membership_id" AS "membership__membership_id", "membership"."account_id" AS "membership__account_id", "membership"."sponsor_account_id" AS "membership__sponsor_account_id", "account"."account_id" AS "account__account_id", "account"."owner_email" AS "account__owner_email", "account"."state" AS "account__state", "account_sponsor"."account_id" AS "account_sponsor__account_id", "account_sponsor"."owner_email" AS "account_sponsor__owner_email", "account_sponsor"."state" AS "account_sponsor__state", "accessgrant"."id" AS "accessgrant__id", "accessgrant"."account_id" AS "accessgrant__account_id", "accessgrant"."principal_id" AS "accessgrant__principal_id", "accessgrant"."has_browse_access" AS "accessgrant__has_browse_access" FROM "memberships" "membership" JOIN "accounts" "account" ON "membership"."account_id" = "account"."account_id" LEFT OUTER JOIN "accounts" "account_sponsor" ON "membership"."sponsor_account_id" = "account_sponsor"."account_id" JOIN "access_grants" "accessgrant" ON (("membership"."account_id" = "accessgrant"."account_id") AND ("accessgrant"."principal_id" = $1)) AND ("accessgrant"."has_browse_access" = $2) ORDER BY "account"."owner_email" ASC LIMIT 20 OFFSET 40
$1 = 4711
